/* eslint-disable no-bitwise -- FNV-1a checksum uses 32-bit unsigned integer arithmetic */
import {describe, expect, it} from 'vite-plus/test';
import type {RgbaImage} from '../../src/engine/types.ts';
import {
	SYNTHETIC_FIXTURES,
	getSyntheticFixture,
	type SyntheticFixtureName,
} from './synthetic.ts';

function fnv1a32(bytes: Uint8ClampedArray): number {
	let hash = 0x81_1c_9d_c5;
	for (const byte of bytes) {
		hash ^= byte;
		hash = Math.imul(hash, 0x01_00_01_93) >>> 0;
	}

	return hash >>> 0;
}

function expectSameBytes(a: RgbaImage, b: RgbaImage): void {
	expect(a.width).toBe(b.width);
	expect(a.height).toBe(b.height);
	expect(a.data.length).toBe(b.data.length);
	expect(a.data).not.toBe(b.data);
	expect(a.data).toEqual(b.data);
}

const EXPECTED_DIMENSIONS: Readonly<
	Record<SyntheticFixtureName, readonly [number, number]>
> = {
	'gradient-64x48': [64, 48],
	'noise-97x61': [97, 61],
	'bands-80x80': [80, 80],
	'alpha-32x32': [32, 32],
};

// Checksums lock the generated bytes so accidental changes to a generator are caught.
const EXPECTED_CHECKSUMS: Readonly<Record<SyntheticFixtureName, number>> = {
	'gradient-64x48': 0xd5_a7_43_b0,
	'noise-97x61': 0xc6_d6_e9_5e,
	'bands-80x80': 0xb1_97_b7_00,
	'alpha-32x32': 0x51_cf_ea_6f,
};

describe('synthetic test fixtures (engine.md section 14.2)', () => {
	it('generates each fixture at the stated size, deterministically, with matching checksum', () => {
		const names = Object.keys(SYNTHETIC_FIXTURES) as SyntheticFixtureName[];
		expect(names).toEqual([
			'gradient-64x48',
			'noise-97x61',
			'bands-80x80',
			'alpha-32x32',
		]);

		for (const name of names) {
			const [expectedWidth, expectedHeight] = EXPECTED_DIMENSIONS[name];
			const first = getSyntheticFixture(name);
			const second = getSyntheticFixture(name);

			expect(first.width).toBe(expectedWidth);
			expect(first.height).toBe(expectedHeight);
			expect(first.data.length).toBe(expectedWidth * expectedHeight * 4);
			expectSameBytes(first, second);
			expect(fnv1a32(first.data), `${name} checksum`).toBe(
				EXPECTED_CHECKSUMS[name],
			);
		}
	});

	it('alpha-32x32 has a transparent bottom-right quarter and opaque pixels elsewhere', () => {
		const image = getSyntheticFixture('alpha-32x32');
		let transparentCount = 0;
		let opaqueCount = 0;
		for (let y = 0; y < image.height; y++) {
			for (let x = 0; x < image.width; x++) {
				const alpha = image.data[(y * image.width + x) * 4 + 3];
				if (x >= 16 && y >= 16) {
					expect(alpha).toBe(0);
					transparentCount++;
				} else {
					expect(alpha).toBe(255);
					opaqueCount++;
				}
			}
		}

		expect(transparentCount).toBe(256);
		expect(opaqueCount).toBe(768);
	});

	it('bands-80x80 has 1 px black separators every 10 rows', () => {
		const image = getSyntheticFixture('bands-80x80');
		for (let band = 0; band < 8; band++) {
			const separatorY = band * 10 + 9;
			for (let x = 0; x < image.width; x++) {
				const p = (separatorY * image.width + x) * 4;
				expect(image.data[p]).toBe(0);
				expect(image.data[p + 1]).toBe(0);
				expect(image.data[p + 2]).toBe(0);
				expect(image.data[p + 3]).toBe(255);
			}
		}
	});
});
